contracts/VastMintFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "./VastMintNFT.sol";

contract VastMintFactory {

    struct CollectionInfo {
        address contractAddress;
        address creator;
        string name;
        string symbol;
        string description;
        string image;
        uint256 maxSupply;
        uint256 mintPrice;
        uint256 whitelistPrice;
        uint256 maxPerWallet;
        uint256 createdAt;
        string slug;
    }

    CollectionInfo[] public collections;
    mapping(address => CollectionInfo[]) public creatorCollections;
    mapping(string => address) public slugToAddress;

    event CollectionCreated(
        address indexed contractAddress,
        address indexed creator,
        string name,
        string slug,
        uint256 createdAt
    );

    function createCollection(
        string memory _name,
        string memory _symbol,
        string memory _description,
        string memory _image,
        uint256 _maxSupply,
        uint256 _mintPrice,
        uint256 _whitelistPrice,
        uint256 _maxPerWallet,
        bytes32 _whitelistRoot,
        string memory _slug
    ) external returns (address) {
        require(slugToAddress[_slug] == address(0), "Slug already taken");
        require(_maxSupply > 0, "Supply must be greater than 0");
        require(bytes(_name).length > 0, "Name required");
        require(bytes(_symbol).length > 0, "Symbol required");
        require(bytes(_slug).length > 0, "Slug required");

        VastMintNFT newCollection = new VastMintNFT(
            _name,
            _symbol,
            _description,
            _image,
            _maxSupply,
            _mintPrice,
            _whitelistPrice,
            _maxPerWallet,
            _whitelistRoot,
            msg.sender
        );

        CollectionInfo memory info = CollectionInfo({
            contractAddress: address(newCollection),
            creator: msg.sender,
            name: _name,
            symbol: _symbol,
            description: _description,
            image: _image,
            maxSupply: _maxSupply,
            mintPrice: _mintPrice,
            whitelistPrice: _whitelistPrice,
            maxPerWallet: _maxPerWallet,
            createdAt: block.timestamp,
            slug: _slug
        });

        collections.push(info);
        creatorCollections[msg.sender].push(info);
        slugToAddress[_slug] = address(newCollection);

        emit CollectionCreated(
            address(newCollection),
            msg.sender,
            _name,
            _slug,
            block.timestamp
        );

        return address(newCollection);
    }

    function getAllCollections() external view returns (CollectionInfo[] memory) {
        return collections;
    }

    function getCreatorCollections(address _creator) external view returns (CollectionInfo[] memory) {
        return creatorCollections[_creator];
    }

    function getCollectionBySlug(string memory _slug) external view returns (CollectionInfo memory) {
        address contractAddr = slugToAddress[_slug];
        require(contractAddr != address(0), "Collection not found");

        for (uint256 i = 0; i < collections.length; i++) {
            if (collections[i].contractAddress == contractAddr) {
                return collections[i];
            }
        }

        revert("Collection not found");
    }

    function totalCollections() external view returns (uint256) {
        return collections.length;
    }
}

contracts/VastMintMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IOwnableNFT {
    function owner() external view returns (address);
}

contract VastMintMarketplace is Ownable, ReentrancyGuard {

    uint256 public platformFeeBps = 200; // 2% platform fee
    uint256 public royaltyBps = 500;     // 5% royalty to creator
    address public treasury;

    struct Listing {
        uint256 listingId;
        address seller;
        address nftContract;
        uint256 tokenId;
        uint256 price;
        bool active;
        uint256 createdAt;
    }

    uint256 public nextListingId = 1;
    mapping(uint256 => Listing) public listings;
    mapping(address => mapping(uint256 => uint256)) public tokenToListingId;

    // creator royalty per NFT contract
    mapping(address => address) public contractCreator;

    event Listed(
        uint256 indexed listingId,
        address indexed seller,
        address indexed nftContract,
        uint256 tokenId,
        uint256 price
    );

    event Sold(
        uint256 indexed listingId,
        address indexed buyer,
        address indexed nftContract,
        uint256 tokenId,
        uint256 price
    );

    event Cancelled(
        uint256 indexed listingId,
        address indexed seller
    );

    constructor(address _treasury) Ownable(msg.sender) {
        require(_treasury != address(0), "Treasury required");
        treasury = _treasury;
    }

    function listNFT(
        address _nftContract,
        uint256 _tokenId,
        uint256 _price
    ) external {
        require(_nftContract != address(0), "NFT contract required");
        require(_price > 0, "Price must be greater than 0");
        IERC721 nft = IERC721(_nftContract);
        require(nft.ownerOf(_tokenId) == msg.sender, "Not token owner");
        require(
            nft.isApprovedForAll(msg.sender, address(this)) ||
            nft.getApproved(_tokenId) == address(this),
            "Marketplace not approved"
        );

        uint256 existingId = tokenToListingId[_nftContract][_tokenId];
        require(existingId == 0 || !listings[existingId].active, "NFT already listed");

        uint256 listingId = nextListingId++;
        listings[listingId] = Listing({
            listingId: listingId,
            seller: msg.sender,
            nftContract: _nftContract,
            tokenId: _tokenId,
            price: _price,
            active: true,
            createdAt: block.timestamp
        });

        tokenToListingId[_nftContract][_tokenId] = listingId;

       if (contractCreator[_nftContract] == address(0)) {
            address creator = IOwnableNFT(_nftContract).owner();
            if (creator != address(0)) {
                contractCreator[_nftContract] = creator;
            }
        }

        emit Listed(listingId, msg.sender, _nftContract, _tokenId, _price);
    }

    function buyNFT(uint256 _listingId) external payable nonReentrant {
        Listing storage listing = listings[_listingId];
        require(listing.active, "Listing not active");
        require(msg.value >= listing.price, "Insufficient payment");
        require(msg.sender != listing.seller, "Cannot buy your own NFT");
        require(IERC721(listing.nftContract).ownerOf(listing.tokenId) == listing.seller, "Seller no longer owns NFT");

        listing.active = false;
        delete tokenToListingId[listing.nftContract][listing.tokenId];

        uint256 platformFee = (listing.price * platformFeeBps) / 10000;
        uint256 royalty = (listing.price * royaltyBps) / 10000;
        uint256 sellerAmount = listing.price - platformFee - royalty;

        // Transfer NFT before funds; nonReentrant and listing deactivation prevent reentry purchases.
        IERC721(listing.nftContract).safeTransferFrom(
            listing.seller,
            msg.sender,
            listing.tokenId
        );

        _sendValue(treasury, platformFee);

        address creator = contractCreator[listing.nftContract];
        if (creator != address(0) && royalty > 0) {
            _sendValue(creator, royalty);
        } else {
            sellerAmount += royalty;
        }

        _sendValue(listing.seller, sellerAmount);

        if (msg.value > listing.price) {
            _sendValue(msg.sender, msg.value - listing.price);
        }

        emit Sold(_listingId, msg.sender, listing.nftContract, listing.tokenId, listing.price);
    }

    function cancelListing(uint256 _listingId) external {
        Listing storage listing = listings[_listingId];
        require(listing.active, "Listing not active");
        require(listing.seller == msg.sender || msg.sender == owner(), "Not authorized");
        listing.active = false;
        delete tokenToListingId[listing.nftContract][listing.tokenId];
        emit Cancelled(_listingId, msg.sender);
    }

    function getActiveListings() external view returns (Listing[] memory) {
        uint256 count = 0;
        for (uint256 i = 1; i < nextListingId; i++) {
            if (_isListingSellable(listings[i])) count++;
        }

        Listing[] memory active = new Listing[](count);
        uint256 index = 0;
        for (uint256 i = 1; i < nextListingId; i++) {
            if (_isListingSellable(listings[i])) {
                active[index++] = listings[i];
            }
        }
        return active;
    }

    function getListingsByContract(address _nftContract) external view returns (Listing[] memory) {
        uint256 count = 0;
        for (uint256 i = 1; i < nextListingId; i++) {
            if (listings[i].nftContract == _nftContract && _isListingSellable(listings[i])) count++;
        }

        Listing[] memory result = new Listing[](count);
        uint256 index = 0;
        for (uint256 i = 1; i < nextListingId; i++) {
            if (listings[i].nftContract == _nftContract && _isListingSellable(listings[i])) {
                result[index++] = listings[i];
            }
        }
        return result;
    }

    function getListingsBySeller(address _seller) external view returns (Listing[] memory) {
        uint256 count = 0;
        for (uint256 i = 1; i < nextListingId; i++) {
            if (listings[i].seller == _seller && _isListingSellable(listings[i])) count++;
        }

        Listing[] memory result = new Listing[](count);
        uint256 index = 0;
        for (uint256 i = 1; i < nextListingId; i++) {
            if (listings[i].seller == _seller && _isListingSellable(listings[i])) {
                result[index++] = listings[i];
            }
        }
        return result;
    }

    function setTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "Treasury required");
        treasury = _treasury;
    }

    function setPlatformFee(uint256 _bps) external onlyOwner {
        require(_bps <= 1000, "Max 10%");
        require(_bps + royaltyBps <= 10000, "Fees exceed price");
        platformFeeBps = _bps;
    }

    function setRoyalty(uint256 _bps) external onlyOwner {
        require(_bps <= 1000, "Max 10%");
        require(platformFeeBps + _bps <= 10000, "Fees exceed price");
        royaltyBps = _bps;
    }

    function _isListingSellable(Listing storage listing) private view returns (bool) {
        if (!listing.active) return false;

        IERC721 nft = IERC721(listing.nftContract);
        try nft.ownerOf(listing.tokenId) returns (address tokenOwner) {
            if (tokenOwner != listing.seller) return false;
        } catch {
            return false;
        }

        bool approvedSingle = false;
bool approvedAll = false;

try nft.getApproved(listing.tokenId) returns (address approved) {
    approvedSingle = (approved == address(this));
} catch {}

try nft.isApprovedForAll(listing.seller, address(this)) returns (bool approvedAll_) {
    approvedAll = approvedAll_;
} catch {}

return approvedSingle || approvedAll;
        
    }

    function _sendValue(address to, uint256 amount) private {
        if (amount == 0) return;
        require(to != address(0), "Payment recipient required");
        (bool success, ) = payable(to).call{value: amount}("");
        require(success, "Payment failed");
    }
}

